proforma_upload_btn.script:
' Upload attachment to IW32 work order
' Reads: {{file_dir}}, {{file_name}}, {{doc_nr}}, {{description}}, {{order}}
' Writes: {{upload_status}}
session.findById("wnd[0]/tbar[0]/okcd").text = "/nIW32"
session.findById("wnd[0]").sendVKey 0
session.findById("wnd[0]/usr/ctxtCAUFVD-AUFNR").text = {{order}}
session.findById("wnd[0]").sendVKey 0
session.findById("wnd[0]/usr/subSUB_ALL:SAPLCOIH:3001/ssubSUB_LEVEL:SAPLCOIH:1100/tabsTS_1100/tabpIHKD").select()
session.findById("wnd[0]/usr/subSUB_ALL:SAPLCOIH:3001/ssubSUB_LEVEL:SAPLCOIH:1100/tabsTS_1100/tabpIHKD/ssubSUB_AUFTRAG:SAPLCOIH:1130/subDVS:SAPLEAMCC_DOC_ALV:0100/cntlDVS_ALV/shellcont/shell").pressToolbarButton "CREATE&ASSIGN"
session.findById("wnd[1]/usr/sub:SAPLSPO4:0300/ctxtSVALD-VALUE[0,21]").text = {{doc_nr}}
session.findById("wnd[1]/usr/sub:SAPLSPO4:0300/txtSVALD-VALUE[2,21]").text = {{description}}
session.findById("wnd[1]/tbar[0]/btn[0]").press()
session.findById("wnd[1]/usr/ctxtDY_PATH").text = {{file_dir}}
session.findById("wnd[1]/usr/ctxtDY_FILENAME").text = {{file_name}}
session.findById("wnd[1]/tbar[0]/btn[0]").press()
session.findById("wnd[0]/tbar[0]/btn[11]").press
sbar_text = session.findById("wnd[0]/sbar").text
sbar_type = session.findById("wnd[0]/sbar").MessageType
{{ upload_status }} = sbar_text
{{ upload_status_type }} = sbar_type

